'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { supabase } from '../../lib/supabase'
import { isAuthenticated, logout, getCurrentAdmin } from '../../lib/auth'
import { 
  FaEdit, FaTrash, FaSave, FaTimes, FaImage, FaPalette, 
  FaTelegram, FaSignOutAlt, FaSpinner, FaUpload, FaEye, 
  FaEyeSlash, FaLink, FaTextHeight, FaPaintBrush, FaPlus, FaCommentDots
} from 'react-icons/fa'
import { 
  getAllTickerItems, 
  addCustomTickerItem, 
  deleteTickerItem, 
  updateTickerOrder, 
  toggleTickerItem 
} from '../../lib/siteConfig'

// ============================================================
// تعريفات الأنواع (Types)
// ============================================================
interface NewsItem {
  id: string
  title: string
  content: string
  category: string
  image: string
  created_at: string
}

interface Settings {
  siteName: string
  telegramUrl: string
  primaryColor: string
  tickerSpeed: number
}

interface HeroSection {
  id?: number
  title: string
  subtitle: string
  background_image: string
  overlay_opacity: number
  button_text: string
  button_link: string
  is_enabled: boolean
}

interface TickerItem {
  id: number
  text_content: string
  link_url: string | null
  link_text: string | null
  order_index: number
  is_active: boolean
  is_external: boolean
}

interface Comment {
  id: string
  author_name: string
  content: string
  news_slug: string
  created_at: string
}

// ============================================================
// المكون الرئيسي
// ============================================================
export default function OwnerPage() {
  const router = useRouter()
  
  // حالات المصادقة
  const [isAuthorized, setIsAuthorized] = useState(false)
  const [adminName, setAdminName] = useState('')
  const [loadingAuth, setLoadingAuth] = useState(true)
  
  // حالات التبويبات
  const [activeTab, setActiveTab] = useState<'news' | 'settings' | 'ticker' | 'hero' | 'comments'>('hero')
  
  // حالات الأخبار
  const [news, setNews] = useState<NewsItem[]>([])
  const [loading, setLoading] = useState(true)
  const [editingNews, setEditingNews] = useState<NewsItem | null>(null)
  
  // حالات الإعدادات العامة
  const [settings, setSettings] = useState<Settings>({
    siteName: 'ديب سورس نيوز',
    telegramUrl: 'https://t.me/deepsourc',
    primaryColor: '#dc2626',
    tickerSpeed: 4000,
  })
  
  // حالات البانر العلوي (Hero Section)
  const [hero, setHero] = useState<HeroSection>({
    title: 'آخر الأخبار العميقة',
    subtitle: 'تحليلات لا تجدها في أي مكان آخر',
    background_image: 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?w=1920',
    overlay_opacity: 20,
    button_text: 'استكشف الأخبار',
    button_link: '/news',
    is_enabled: true,
  })
  
  // حالات الشريط المتحرك
  const [tickerItems, setTickerItems] = useState<TickerItem[]>([])
  const [showAddModal, setShowAddModal] = useState(false)
  const [newTickerText, setNewTickerText] = useState('')
  const [newTickerLink, setNewTickerLink] = useState('')
  const [newTickerLinkText, setNewTickerLinkText] = useState('')
  const [newTickerIsExternal, setNewTickerIsExternal] = useState(false)
  
  // حالات إدارة التعليقات
  const [comments, setComments] = useState<Comment[]>([])
  const [commentsLoading, setCommentsLoading] = useState(true)
  
  const [message, setMessage] = useState('')
  const [uploading, setUploading] = useState(false)

  // ============================================================
  // التحقق من صلاحية الدخول
  // ============================================================
  useEffect(() => {
    const checkAuth = () => {
      const authenticated = isAuthenticated()
      if (!authenticated) {
        router.push('/login')
      } else {
        const admin = getCurrentAdmin()
        setAdminName(admin.name || 'المالك')
        setIsAuthorized(true)
      }
      setLoadingAuth(false)
    }
    checkAuth()
  }, [router])

  // ============================================================
  // جلب البيانات من قاعدة البيانات
  // ============================================================
  const fetchNews = async () => {
    setLoading(true)
    const { data } = await supabase
      .from('news')
      .select('*')
      .order('created_at', { ascending: false })
    if (data) setNews(data as NewsItem[])
    setLoading(false)
  }

  const fetchSettings = async () => {
    const { data } = await supabase
      .from('site_settings')
      .select('*')
      .single()
    if (data) {
      setSettings({
        siteName: data.site_name || 'ديب سورس نيوز',
        telegramUrl: data.telegram_url || 'https://t.me/deepsourc',
        primaryColor: data.primary_color || '#dc2626',
        tickerSpeed: data.ticker_speed || 4000,
      })
    }
  }

  const fetchHero = async () => {
    const { data, error } = await supabase
      .from('hero_section')
      .select('*')
      .single()
    
    if (data) {
      setHero({
        title: data.title || 'آخر الأخبار العميقة',
        subtitle: data.subtitle || 'تحليلات لا تجدها في أي مكان آخر',
        background_image: data.background_image || 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?w=1920',
        overlay_opacity: data.overlay_opacity || 20,
        button_text: data.button_text || 'استكشف الأخبار',
        button_link: data.button_link || '/news',
        is_enabled: data.is_enabled !== false,
      })
    }
  }

  const fetchTickerItems = async () => {
    const items = await getAllTickerItems()
    setTickerItems(items)
  }

  const fetchComments = async () => {
    setCommentsLoading(true)
    const { data } = await supabase
      .from('comments')
      .select('*')
      .order('created_at', { ascending: false })
    
    if (data) setComments(data as Comment[])
    setCommentsLoading(false)
  }

  useEffect(() => {
    if (isAuthorized) {
      fetchNews()
      fetchSettings()
      fetchHero()
      fetchTickerItems()
      fetchComments()
    }
  }, [isAuthorized])

  // ============================================================
  // دوال إدارة الأخبار
  // ============================================================
  const handleDelete = async (id: string) => {
    if (!confirm('هل أنت متأكد من حذف هذا الخبر؟')) return
    const { error } = await supabase.from('news').delete().eq('id', id)
    if (!error) {
      setMessage('✅ تم حذف الخبر بنجاح')
      fetchNews()
    } else {
      setMessage('❌ خطأ في الحذف: ' + error.message)
    }
  }

  const handleUpdate = async (newsItem: NewsItem) => {
    const { error } = await supabase
      .from('news')
      .update({
        title: newsItem.title,
        content: newsItem.content,
        category: newsItem.category,
        image: newsItem.image,
      })
      .eq('id', newsItem.id)
    if (!error) {
      setMessage('✅ تم تحديث الخبر بنجاح')
      setEditingNews(null)
      fetchNews()
    } else {
      setMessage('❌ خطأ في التحديث: ' + error.message)
    }
  }

  // ============================================================
  // دوال إعدادات الموقع
  // ============================================================
  const updateSettings = async () => {
    const { data: existing, error: checkError } = await supabase
      .from('site_settings')
      .select('id')
      .maybeSingle()

    if (checkError && checkError.code !== 'PGRST116') {
      setMessage('❌ خطأ: ' + checkError.message)
      return
    }

    let result
    if (existing) {
      result = await supabase
        .from('site_settings')
        .update({
          telegram_url: settings.telegramUrl,
          primary_color: settings.primaryColor,
          ticker_speed: settings.tickerSpeed,
          updated_at: new Date().toISOString(),
        })
        .eq('id', existing.id)
    } else {
      result = await supabase
        .from('site_settings')
        .insert([{
          site_name: settings.siteName,
          telegram_url: settings.telegramUrl,
          primary_color: settings.primaryColor,
          ticker_speed: settings.tickerSpeed,
        }])
    }

    if (result?.error) {
      setMessage('❌ خطأ في حفظ الإعدادات: ' + result.error.message)
    } else {
      setMessage('✅ تم حفظ الإعدادات بنجاح!')
    }
  }

  // ============================================================
  // دوال البانر العلوي (Hero Section)
  // ============================================================
  const handleHeroImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    setUploading(true)
    try {
      const fileExt = file.name.split('.').pop()
      const fileName = `hero-${Date.now()}.${fileExt}`
      const filePath = `hero/${fileName}`

      const { error: uploadError } = await supabase.storage
        .from('news-images')
        .upload(filePath, file, { cacheControl: '3600', upsert: true })

      if (uploadError) throw uploadError

      const { data: publicUrlData } = supabase.storage
        .from('news-images')
        .getPublicUrl(filePath)

      setHero(prev => ({ ...prev, background_image: publicUrlData.publicUrl }))
      setMessage('✅ تم رفع صورة الخلفية بنجاح')
    } catch (error) {
      setMessage('❌ خطأ في رفع الصورة: ' + (error as Error).message)
    }
    setUploading(false)
  }

  const saveHero = async () => {
    const { data: existing } = await supabase
      .from('hero_section')
      .select('id')
      .maybeSingle()

    let result
    if (existing) {
      result = await supabase
        .from('hero_section')
        .update({
          title: hero.title,
          subtitle: hero.subtitle,
          background_image: hero.background_image,
          overlay_opacity: hero.overlay_opacity,
          button_text: hero.button_text,
          button_link: hero.button_link,
          is_enabled: hero.is_enabled,
          updated_at: new Date().toISOString(),
        })
        .eq('id', existing.id)
    } else {
      result = await supabase
        .from('hero_section')
        .insert([{
          title: hero.title,
          subtitle: hero.subtitle,
          background_image: hero.background_image,
          overlay_opacity: hero.overlay_opacity,
          button_text: hero.button_text,
          button_link: hero.button_link,
          is_enabled: hero.is_enabled,
        }])
    }

    if (result?.error) {
      setMessage('❌ خطأ في حفظ البانر: ' + result.error.message)
    } else {
      setMessage('✅ تم حفظ البانر بنجاح!')
    }
  }

  // ============================================================
  // دوال الشريط المتحرك (Ticker)
  // ============================================================
  const handleAddToTicker = async () => {
    if (!newTickerText.trim()) {
      setMessage('❌ الرجاء إدخال نص للعنصر')
      return
    }

    const { error } = await addCustomTickerItem(
      newTickerText,
      newTickerLink || '',
      newTickerLinkText || '',
      newTickerIsExternal
    )
    
    if (!error) {
      setMessage('✅ تم إضافة العنصر إلى الشريط')
      setShowAddModal(false)
      setNewTickerText('')
      setNewTickerLink('')
      setNewTickerLinkText('')
      setNewTickerIsExternal(false)
      fetchTickerItems()
    } else {
      setMessage('❌ خطأ: ' + error.message)
    }
  }

  const handleRemoveFromTicker = async (id: number) => {
    if (!confirm('هل تريد إزالة هذا العنصر من الشريط؟')) return
    const { error } = await deleteTickerItem(id)
    if (!error) {
      setMessage('✅ تم إزالة العنصر من الشريط')
      fetchTickerItems()
    } else {
      setMessage('❌ خطأ: ' + error.message)
    }
  }

  const handleToggleActive = async (id: number, currentStatus: boolean) => {
    const { error } = await toggleTickerItem(id, !currentStatus)
    if (!error) {
      setMessage(`✅ ${currentStatus ? 'تم تعطيل' : 'تم تفعيل'} العنصر في الشريط`)
      fetchTickerItems()
    }
  }

  const moveUp = async (index: number) => {
    if (index === 0) return
    const newItems = [...tickerItems]
    const temp = newItems[index]
    newItems[index] = newItems[index - 1]
    newItems[index - 1] = temp
    newItems.forEach((item, i) => item.order_index = i)
    await updateTickerOrder(newItems)
    fetchTickerItems()
  }

  const moveDown = async (index: number) => {
    if (index === tickerItems.length - 1) return
    const newItems = [...tickerItems]
    const temp = newItems[index]
    newItems[index] = newItems[index + 1]
    newItems[index + 1] = temp
    newItems.forEach((item, i) => item.order_index = i)
    await updateTickerOrder(newItems)
    fetchTickerItems()
  }

  // ============================================================
  // دوال إدارة التعليقات
  // ============================================================
  const handleDeleteComment = async (id: string) => {
    if (!confirm('هل تريد حذف هذا التعليق؟')) return
    const { error } = await supabase.from('comments').delete().eq('id', id)
    if (!error) {
      setMessage('✅ تم حذف التعليق')
      fetchComments()
    } else {
      setMessage('❌ خطأ في الحذف: ' + error.message)
    }
  }

  const handleLogout = () => {
    logout()
    router.push('/login')
  }

  // ============================================================
  // حالة التحميل
  // ============================================================
  if (loadingAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <FaSpinner className="animate-spin text-red-600 text-4xl" />
      </div>
    )
  }

  if (!isAuthorized) {
    return null
  }

  // ============================================================
  // واجهة المستخدم
  // ============================================================
  return (
    <div className="min-h-screen bg-gray-50 dark:bg-darkBg py-12">
      <div className="container-custom">
        {/* Header */}
        <div className="flex justify-between items-center mb-8 flex-wrap gap-4">
          <h1 className="text-3xl font-bold border-r-4 border-red-600 pr-4">
            👑 لوحة تحكم المالك
          </h1>
          <div className="flex items-center gap-4">
            <span className="text-gray-600 dark:text-gray-400">مرحباً، {adminName}</span>
            <button
              onClick={handleLogout}
              className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition"
            >
              <FaSignOutAlt /> تسجيل خروج
            </button>
          </div>
        </div>

        {/* رسالة الحالة */}
        {message && (
          <div className={`p-4 rounded-lg mb-6 ${message.includes('✅') ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' : 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'}`}>
            {message}
          </div>
        )}

        {/* أزرار التبويبات */}
        <div className="flex gap-4 mb-8 border-b border-gray-200 dark:border-gray-800 pb-4 flex-wrap">
          <button 
            onClick={() => setActiveTab('hero')}
            className={`px-6 py-2 rounded-lg transition flex items-center gap-2 ${activeTab === 'hero' ? 'bg-red-600 text-white' : 'bg-gray-200 dark:bg-gray-800 hover:bg-gray-300 dark:hover:bg-gray-700'}`}
          >
            <FaImage /> البانر العلوي
          </button>
          <button 
            onClick={() => setActiveTab('news')}
            className={`px-6 py-2 rounded-lg transition flex items-center gap-2 ${activeTab === 'news' ? 'bg-red-600 text-white' : 'bg-gray-200 dark:bg-gray-800 hover:bg-gray-300 dark:hover:bg-gray-700'}`}
          >
            <FaEdit /> إدارة الأخبار
          </button>
          <button 
            onClick={() => setActiveTab('settings')}
            className={`px-6 py-2 rounded-lg transition flex items-center gap-2 ${activeTab === 'settings' ? 'bg-red-600 text-white' : 'bg-gray-200 dark:bg-gray-800 hover:bg-gray-300 dark:hover:bg-gray-700'}`}
          >
            <FaPalette /> إعدادات الموقع
          </button>
          <button 
            onClick={() => setActiveTab('ticker')}
            className={`px-6 py-2 rounded-lg transition flex items-center gap-2 ${activeTab === 'ticker' ? 'bg-red-600 text-white' : 'bg-gray-200 dark:bg-gray-800 hover:bg-gray-300 dark:hover:bg-gray-700'}`}
          >
            <FaPaintBrush /> الشريط المتحرك
          </button>
          <button 
            onClick={() => setActiveTab('comments')}
            className={`px-6 py-2 rounded-lg transition flex items-center gap-2 ${activeTab === 'comments' ? 'bg-red-600 text-white' : 'bg-gray-200 dark:bg-gray-800 hover:bg-gray-300 dark:hover:bg-gray-700'}`}
          >
            <FaCommentDots /> إدارة التعليقات
          </button>
        </div>

        {/* ============================================================
            تبويب البانر العلوي (HERO SECTION)
        ============================================================ */}
        {activeTab === 'hero' && (
          <div className="bg-white dark:bg-cardBg rounded-xl p-6 border border-gray-200 dark:border-gray-800 space-y-6">
            <h2 className="text-2xl font-bold mb-4">🖼️ تخصيص البانر العلوي</h2>
            
            <div className="bg-gray-100 dark:bg-gray-800 p-4 rounded-lg">
              <p className="text-sm text-gray-500 mb-2">معاينة حية (كما ستظهر في الموقع)</p>
              <div 
                className="relative rounded-xl overflow-hidden h-48 bg-cover bg-center"
                style={{ backgroundImage: `url(${hero.background_image})` }}
              >
                <div 
                  className="absolute inset-0 flex items-center justify-center text-center p-4"
                  style={{ backgroundColor: `rgba(0,0,0,${hero.overlay_opacity / 100})` }}
                >
                  <div>
                    <h3 className="text-2xl font-bold text-white">{hero.title}</h3>
                    <p className="text-gray-200">{hero.subtitle}</p>
                    {hero.button_text && (
                      <button className="mt-3 bg-red-600 text-white px-4 py-1 rounded-full text-sm">
                        {hero.button_text}
                      </button>
                    )}
                  </div>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="md:col-span-2">
                <label className="block font-bold mb-2">🖼️ صورة الخلفية</label>
                <div className="flex gap-3 flex-wrap">
                  <button 
                    onClick={() => document.getElementById('heroImageInput')?.click()}
                    className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2"
                    disabled={uploading}
                  >
                    <FaUpload /> {uploading ? 'جاري الرفع...' : 'رفع صورة جديدة'}
                  </button>
                  <input id="heroImageInput" type="file" accept="image/*" className="hidden" onChange={handleHeroImageUpload} />
                  <input 
                    type="text" 
                    value={hero.background_image} 
                    onChange={(e) => setHero({ ...hero, background_image: e.target.value })}
                    placeholder="أو أدخل رابط الصورة"
                    className="flex-1 p-2 rounded-lg border dark:bg-gray-900"
                  />
                </div>
              </div>
              
              <div>
                <label className="block font-bold mb-2">📝 العنوان الرئيسي</label>
                <input 
                  type="text" 
                  value={hero.title} 
                  onChange={(e) => setHero({ ...hero, title: e.target.value })}
                  className="w-full p-3 rounded-lg border dark:bg-gray-900"
                />
              </div>
              
              <div>
                <label className="block font-bold mb-2">📄 النص الثانوي</label>
                <input 
                  type="text" 
                  value={hero.subtitle} 
                  onChange={(e) => setHero({ ...hero, subtitle: e.target.value })}
                  className="w-full p-3 rounded-lg border dark:bg-gray-900"
                />
              </div>
              
              <div>
                <label className="block font-bold mb-2">🔘 نص الزر</label>
                <input 
                  type="text" 
                  value={hero.button_text} 
                  onChange={(e) => setHero({ ...hero, button_text: e.target.value })}
                  className="w-full p-3 rounded-lg border dark:bg-gray-900"
                />
              </div>
              
              <div>
                <label className="block font-bold mb-2">🔗 رابط الزر</label>
                <input 
                  type="text" 
                  value={hero.button_link} 
                  onChange={(e) => setHero({ ...hero, button_link: e.target.value })}
                  className="w-full p-3 rounded-lg border dark:bg-gray-900"
                />
              </div>
              
              <div>
                <label className="block font-bold mb-2">🎨 شفافية الطبقة ({hero.overlay_opacity}%)</label>
                <input 
                  type="range" 
                  min="0" 
                  max="90" 
                  value={hero.overlay_opacity} 
                  onChange={(e) => setHero({ ...hero, overlay_opacity: parseInt(e.target.value) })}
                  className="w-full"
                />
              </div>
              
              <div>
                <label className="block font-bold mb-2">✅ حالة القسم</label>
                <button 
                  onClick={() => setHero({ ...hero, is_enabled: !hero.is_enabled })}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition ${hero.is_enabled ? 'bg-green-600 text-white' : 'bg-gray-600 text-white'}`}
                >
                  {hero.is_enabled ? <FaEye /> : <FaEyeSlash />}
                  {hero.is_enabled ? 'مفعل' : 'معطل'}
                </button>
              </div>
            </div>
            
            <div className="flex gap-3 pt-4 border-t">
              <button onClick={saveHero} className="bg-red-600 hover:bg-red-700 text-white px-6 py-2 rounded-lg flex items-center gap-2">
                <FaSave /> حفظ البانر
              </button>
            </div>
          </div>
        )}

        {/* ============================================================
            تبويب إدارة الأخبار (NEWS)
        ============================================================ */}
        {activeTab === 'news' && (
          <div className="space-y-4">
            {loading ? (
              <p className="text-center py-20">جاري التحميل...</p>
            ) : news.length === 0 ? (
              <p className="text-center py-20 text-gray-500">لا توجد أخبار بعد</p>
            ) : (
              news.map((item) => (
                <div key={item.id} className="bg-white dark:bg-cardBg rounded-xl p-4 border border-gray-200 dark:border-gray-800 shadow-sm">
                  {editingNews?.id === item.id ? (
                    <div className="space-y-3">
                      <input 
                        type="text" 
                        value={editingNews.title} 
                        onChange={(e) => setEditingNews({ ...editingNews, title: e.target.value })}
                        className="w-full p-2 rounded-lg border dark:bg-gray-900"
                      />
                      <textarea 
                        value={editingNews.content} 
                        onChange={(e) => setEditingNews({ ...editingNews, content: e.target.value })}
                        rows={5}
                        className="w-full p-2 rounded-lg border dark:bg-gray-900"
                      />
                      <div className="flex gap-2">
                        <button onClick={() => handleUpdate(editingNews)} className="bg-green-600 text-white px-4 py-2 rounded-lg flex items-center gap-2"><FaSave /> حفظ</button>
                        <button onClick={() => setEditingNews(null)} className="bg-gray-600 text-white px-4 py-2 rounded-lg flex items-center gap-2"><FaTimes /> إلغاء</button>
                      </div>
                    </div>
                  ) : (
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-bold text-lg">{item.title}</h3>
                        <p className="text-gray-500 text-sm">{item.category || 'عام'} • {new Date(item.created_at).toLocaleDateString('ar-EG')}</p>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => setEditingNews(item)} className="text-blue-500 hover:text-blue-600 p-2"><FaEdit size={20} /></button>
                        <button onClick={() => handleDelete(item.id)} className="text-red-500 hover:text-red-600 p-2"><FaTrash size={20} /></button>
                      </div>
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        )}

        {/* ============================================================
            تبويب إعدادات الموقع (SETTINGS)
        ============================================================ */}
        {activeTab === 'settings' && (
          <div className="bg-white dark:bg-cardBg rounded-xl p-6 border border-gray-200 dark:border-gray-800 space-y-6">
            <div>
              <label className="block font-bold mb-2 flex items-center gap-2">
                <FaTelegram className="text-blue-500" /> رابط تليجرام
              </label>
              <input 
                type="url" 
                value={settings.telegramUrl} 
                onChange={(e) => setSettings({ ...settings, telegramUrl: e.target.value })}
                className="w-full p-3 rounded-lg border dark:bg-gray-900"
              />
            </div>
            
            <div>
              <label className="block font-bold mb-2">اللون الأساسي للموقع</label>
              <div className="flex items-center gap-4 flex-wrap">
                <input 
                  type="color" 
                  value={settings.primaryColor} 
                  onChange={(e) => setSettings({ ...settings, primaryColor: e.target.value })}
                  className="w-16 h-16 rounded cursor-pointer border"
                />
                <input 
                  type="text" 
                  value={settings.primaryColor} 
                  onChange={(e) => setSettings({ ...settings, primaryColor: e.target.value })}
                  className="flex-1 p-3 rounded-lg border dark:bg-gray-900"
                />
              </div>
            </div>
            
            <div>
              <label className="block font-bold mb-2">سرعة الشريط المتحرك (ميلي ثانية)</label>
              <input 
                type="number" 
                value={settings.tickerSpeed} 
                onChange={(e) => setSettings({ ...settings, tickerSpeed: parseInt(e.target.value) || 4000 })}
                className="w-full p-3 rounded-lg border dark:bg-gray-900"
              />
            </div>
            
            <button onClick={updateSettings} className="bg-red-600 hover:bg-red-700 text-white px-6 py-3 rounded-lg flex items-center gap-2 transition w-full justify-center font-bold">
              <FaSave /> حفظ جميع الإعدادات
            </button>
          </div>
        )}

        {/* ============================================================
            تبويب الشريط المتحرك (TICKER)
        ============================================================ */}
        {activeTab === 'ticker' && (
          <div className="bg-white dark:bg-cardBg rounded-xl p-6 border border-gray-200 dark:border-gray-800 space-y-6">
            <div className="flex justify-between items-center flex-wrap gap-4">
              <h2 className="text-2xl font-bold">📢 إدارة الشريط المتحرك</h2>
              <button 
                onClick={() => setShowAddModal(true)}
                className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition"
              >
                <FaPlus /> إضافة عنصر جديد
              </button>
            </div>

            <p className="text-gray-500 text-sm">
              يمكنك إضافة أي نص تريده إلى الشريط (إعلانات، تنبيهات، روابط). العناصر النشطة فقط هي التي تظهر.
            </p>

            {tickerItems.length === 0 ? (
              <div className="text-center py-12 bg-gray-50 dark:bg-gray-800 rounded-lg">
                <p className="text-gray-500">لا توجد عناصر في الشريط بعد</p>
                <p className="text-gray-400 text-sm mt-1">اضغط على "إضافة عنصر جديد" لإضافة أول عنصر</p>
              </div>
            ) : (
              <div className="space-y-3">
                {tickerItems.map((item, index) => (
                  <div key={item.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700">
                    <div className="flex items-center gap-4 flex-1">
                      <span className="text-gray-400 text-sm w-8">{index + 1}</span>
                      <div className="flex-1">
                        <p className="font-medium">{item.text_content}</p>
                        {item.link_url && (
                          <p className="text-xs text-blue-500 mt-1">
                            🔗 {item.link_url} {item.link_text && `(${item.link_text})`}
                          </p>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <button onClick={() => moveUp(index)} disabled={index === 0} className="p-2 text-gray-500 hover:text-blue-500 disabled:opacity-30">↑</button>
                      <button onClick={() => moveDown(index)} disabled={index === tickerItems.length - 1} className="p-2 text-gray-500 hover:text-blue-500 disabled:opacity-30">↓</button>
                      <button onClick={() => handleToggleActive(item.id, item.is_active)} className={`p-2 rounded ${item.is_active ? 'text-green-500' : 'text-gray-400'}`}>
                        {item.is_active ? <FaEye /> : <FaEyeSlash />}
                      </button>
                      <button onClick={() => handleRemoveFromTicker(item.id)} className="p-2 text-red-500 hover:text-red-700">
                        <FaTrash />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* مودال إضافة عنصر جديد */}
            {showAddModal && (
              <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
                <div className="bg-white dark:bg-gray-900 rounded-xl p-6 w-full max-w-lg mx-4">
                  <h3 className="text-xl font-bold mb-4">➕ إضافة عنصر جديد إلى الشريط</h3>
                  
                  <div className="space-y-4">
                    <div>
                      <label className="block font-bold mb-2">النص *</label>
                      <input 
                        type="text" 
                        value={newTickerText} 
                        onChange={(e) => setNewTickerText(e.target.value)}
                        placeholder="مثال: 🔥 عاجل: حدث مهم في المنطقة"
                        className="w-full p-3 rounded-lg border dark:bg-gray-800"
                      />
                    </div>
                    
                    <div>
                      <label className="block font-bold mb-2">رابط (اختياري)</label>
                      <input 
                        type="text" 
                        value={newTickerLink} 
                        onChange={(e) => setNewTickerLink(e.target.value)}
                        placeholder="مثال: /news/important-event  أو https://example.com"
                        className="w-full p-3 rounded-lg border dark:bg-gray-800"
                      />
                    </div>
                    
                    <div>
                      <label className="block font-bold mb-2">نص الرابط (اختياري)</label>
                      <input 
                        type="text" 
                        value={newTickerLinkText} 
                        onChange={(e) => setNewTickerLinkText(e.target.value)}
                        placeholder="مثال: اقرأ المزيد"
                        className="w-full p-3 rounded-lg border dark:bg-gray-800"
                      />
                    </div>
                    
                    <div className="flex items-center gap-3">
                      <input 
                        type="checkbox" 
                        id="isExternal" 
                        checked={newTickerIsExternal} 
                        onChange={(e) => setNewTickerIsExternal(e.target.checked)}
                        className="w-5 h-5"
                      />
                      <label htmlFor="isExternal">رابط خارجي (يفتح في نافذة جديدة)</label>
                    </div>
                  </div>
                  
                  <div className="flex gap-3 mt-6">
                    <button onClick={handleAddToTicker} className="bg-red-600 text-white px-4 py-2 rounded-lg flex-1">إضافة</button>
                    <button 
                      onClick={() => {
                        setShowAddModal(false)
                        setNewTickerText('')
                        setNewTickerLink('')
                        setNewTickerLinkText('')
                        setNewTickerIsExternal(false)
                      }} 
                      className="bg-gray-500 text-white px-4 py-2 rounded-lg flex-1"
                    >
                      إلغاء
                    </button>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* ============================================================
            تبويب إدارة التعليقات (COMMENTS)
        ============================================================ */}
        {activeTab === 'comments' && (
          <div className="bg-white dark:bg-cardBg rounded-xl p-6 border border-gray-200 dark:border-gray-800">
            <h2 className="text-2xl font-bold mb-4 flex items-center gap-2">
              <FaCommentDots className="text-red-600" /> 💬 إدارة التعليقات
            </h2>
            
            <p className="text-gray-500 text-sm mb-6">
              جميع التعليقات التي كتبها الزوار على الأخبار. يمكنك حذف أي تعليق غير مناسب.
            </p>
            
            {commentsLoading ? (
              <div className="text-center py-12">
                <div className="inline-block w-8 h-8 border-4 border-red-500 border-t-transparent rounded-full animate-spin"></div>
                <p className="mt-2 text-gray-500">جاري تحميل التعليقات...</p>
              </div>
            ) : comments.length === 0 ? (
              <div className="text-center py-12 bg-gray-50 dark:bg-gray-800 rounded-lg">
                <FaCommentDots className="text-gray-400 text-4xl mx-auto mb-3" />
                <p className="text-gray-500">لا توجد تعليقات بعد</p>
                <p className="text-gray-400 text-sm mt-1">عندما يكتب الزوار تعليقات، ستظهر هنا</p>
              </div>
            ) : (
              <div className="space-y-4">
                <div className="flex justify-between items-center mb-4">
                  <p className="text-sm text-gray-500">إجمالي التعليقات: {comments.length}</p>
                </div>
                
                {comments.map((comment) => (
                  <div key={comment.id} className="p-4 bg-gray-50 dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700">
                    <div className="flex justify-between items-start flex-wrap gap-3">
                      <div className="flex-1">
                        <div className="flex items-center gap-3 flex-wrap mb-2">
                          <span className="font-bold text-red-600 dark:text-red-400">
                            {comment.author_name}
                          </span>
                          <span className="text-xs text-gray-500 bg-gray-200 dark:bg-gray-700 px-2 py-0.5 rounded">
                            {comment.news_slug}
                          </span>
                          <span className="text-xs text-gray-400">
                            {new Date(comment.created_at).toLocaleString('ar-EG')}
                          </span>
                        </div>
                        <p className="text-gray-700 dark:text-gray-300 leading-relaxed">
                          {comment.content}
                        </p>
                      </div>
                      <button 
                        onClick={() => handleDeleteComment(comment.id)}
                        className="bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-lg transition flex items-center gap-2"
                      >
                        <FaTrash size={14} /> حذف
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
            
            <div className="mt-6 bg-blue-50 dark:bg-blue-950/30 p-4 rounded-lg">
              <p className="text-sm text-blue-700 dark:text-blue-400">
                💡 <strong>ملاحظة:</strong> التعليقات تظهر مباشرة في صفحات الأخبار. يمكنك حذف أي تعليق غير مرغوب فيه من هنا.
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}